@Controller('orders')
export class OrdersController {
  constructor(private readonly orders: OrdersService) {}

  @Get(':id')
  @Render('orders/show')                       // dispatcher: view chosen by decorator
  async show(@Param('id') id: string): Promise<{ order: OrderView }> {
    const order = await this.orders.find(id);  // worker services the request
    return { order };
  }
}
